function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const span = [1500, 3000, 100000][int(0, 2)];
    return [Array.from({ length: 2000 }, () => int(1, span))];
